DROP TABLE IF EXISTS `cl_secondhand_goods`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cl_secondhand_goods` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '发布者ID',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '商品标题',
  `category` varchar(50) NOT NULL DEFAULT '' COMMENT '分类：digital/book/life/sport/other',
  `price` varchar(25) NOT NULL DEFAULT '0.00' COMMENT '售价',
  `original_price` varchar(25) NOT NULL DEFAULT '0.00' COMMENT '原价',
  `description` text COMMENT '商品描述',
  `images` text COMMENT '图片URL，逗号分隔',
  `location` varchar(100) DEFAULT '' COMMENT '交易地点',
  `contact` varchar(50) DEFAULT '' COMMENT '联系方式',
  `status` enum('1','2','3') NOT NULL DEFAULT '1' COMMENT '1=上架 2=已售出 3=下架',
  `sell_order_no` varchar(32) DEFAULT '' COMMENT '成交订单号',
  `created_at` varchar(25) NOT NULL DEFAULT '0' COMMENT '发布时间',
  `updated_at` varchar(25) DEFAULT '0' COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `status` (`status`),
  FULLTEXT KEY `idx_search` (`title`,`description`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

