DROP TABLE IF EXISTS `cl_secondhand_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cl_secondhand_order` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) NOT NULL DEFAULT '' COMMENT '商户订单号(对接易支付)',
  `goods_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `buyer_uid` int(11) NOT NULL DEFAULT '0' COMMENT '买家ID',
  `seller_uid` int(11) NOT NULL DEFAULT '0' COMMENT '卖家ID',
  `pay_amount` varchar(25) NOT NULL DEFAULT '0.00' COMMENT '实付金额',
  `pay_type` varchar(20) DEFAULT '' COMMENT 'alipay/wxpay/qqpay',
  `epay_trade_no` varchar(64) DEFAULT '' COMMENT '易支付交易号',
  `order_status` enum('0','1','2','3','4','5') NOT NULL DEFAULT '0' COMMENT '0=待支付 1=已付款(平台托管) 2=卖家已发货 3=买家已确认收货 4=平台已打款 5=交易完成',
  `seller_alipay` varchar(50) DEFAULT '' COMMENT '卖家支付宝账号',
  `create_time` varchar(25) NOT NULL DEFAULT '0' COMMENT '下单时间',
  `pay_time` varchar(25) DEFAULT '0' COMMENT '付款时间',
  `ship_time` varchar(25) DEFAULT '0' COMMENT '发货时间',
  `confirm_time` varchar(25) DEFAULT '0' COMMENT '确认收货时间',
  `transfer_time` varchar(25) DEFAULT '0' COMMENT '平台打款时间',
  `remark` text,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_no` (`order_no`),
  KEY `goods_id` (`goods_id`),
  KEY `buyer_uid` (`buyer_uid`),
  KEY `seller_uid` (`seller_uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

