CREATE TABLE `cl_system_notice` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `to_uid` int(11) NOT NULL DEFAULT '0' COMMENT '接收用户ID',
  `type` varchar(20) NOT NULL DEFAULT '' COMMENT '消息类型：order/系统',
  `title` varchar(100) NOT NULL DEFAULT '' COMMENT '消息标题',
  `content` text NOT NULL COMMENT '消息内容',
  `order_no` varchar(32) DEFAULT '' COMMENT '关联订单号',
  `is_read` enum('0','1') NOT NULL DEFAULT '0' COMMENT '0=未读 1=已读',
  `create_time` varchar(25) NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `to_uid` (`to_uid`),
  KEY `is_read` (`is_read`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
